def _apply_qc_mask(df, constraints):
    """Apply bounds/items/conditional constraints to df and return a boolean Series.

    Mirrors the non-plotting logic of combine_tools.apply_qc but works directly
    with DANDI column names and has no opto_list special-casing or plotting.
    Missing columns are silently skipped.
    """
    mask = pd.Series(True, index=df.index)
    for col, cfg in constraints.items():
        if col not in df.columns:
            logger.debug(f"_apply_qc_mask: column '{col}' not in DataFrame, skipping")
            continue
        if 'bounds' in cfg:
            lb, ub = np.array(cfg['bounds'], dtype=float)
            if not np.isnan(lb):
                mask &= df[col] >= lb
            if not np.isnan(ub):
                mask &= df[col] <= ub
        elif 'items' in cfg:
            mask &= df[col].isin(cfg['items'])
        elif 'conditional' in cfg:
            cond_mask = pd.Series(False, index=df.index)
            last_condition = None
            for cond in cfg['conditional']:
                if 'if' in cond:
                    for dep_col, (op, val) in cond['if'].items():
                        if dep_col not in df.columns:
                            continue
                        ops = {'<': df[dep_col].__lt__, '<=': df[dep_col].__le__,
                               '>': df[dep_col].__gt__, '>=': df[dep_col].__ge__,
                               '==': df[dep_col].__eq__}
                        last_condition = ops[op](val)
                    lb, ub = np.array(cond['bounds'], dtype=float)
                    bounds_mask = pd.Series(True, index=df.index)
                    if not np.isnan(lb):
                        bounds_mask &= df[col] >= lb
                    if not np.isnan(ub):
                        bounds_mask &= df[col] <= ub
                    cond_mask |= (last_condition & bounds_mask)
                elif 'else' in cond and last_condition is not None:
                    lb, ub = np.array(cond['bounds'], dtype=float)
                    bounds_mask = pd.Series(True, index=df.index)
                    if not np.isnan(lb):
                        bounds_mask &= df[col] >= lb
                    if not np.isnan(ub):
                        bounds_mask &= df[col] <= ub
                    cond_mask |= (~last_condition & bounds_mask)
            mask &= cond_mask
    return mask


